import React from "react";
import DateKeyApi from "../API/DateKeyApi";
import TimezoneApi from "../API/TimezoneApi";
import DateTimeApi from "../API/DateTimeApi";
import '../App.css';


function Issues(){
    return(
            <div className="App">
                <h2> Réglagles de l'API SNCF </h2>
                <DateKeyApi/><br/>
                <TimezoneApi/><br/>
                <DateTimeApi/>  
                GMT (UCT+00)
            </div>
    )
}

export default Issues
